for (let step = 0; step < MAX_STEPS; step++) {
  const decision = await model.respond(context);
  if (decision.type === 'final') return decision.output;

  const call = validateToolCall(decision.toolCall);
  await authorize(call, userPolicy);
  const observation = await runInSandbox(call);
  context = compact([...context, decision, observation]);
}

